      writeValue(buffer, value.encode());
    }    else if (value is KeyInfo) {
      buffer.putUint8(132);
      writeValue(buffer, value.encode());
    }    else if (value is HttpRequestData) {
      buffer.putUint8(133);
      writeValue(buffer, value.encode());
    }    else if (value is HttpResponseData) {
      buffer.putUint8(134);
      writeValue(buffer, value.encode());
    }    else if (value is ServiceStatus) {
      buffer.putUint8(135);
      writeValue(buffer, value.encode());
    }    else if (value is StartupState) {
      buffer.putUint8(136);
      writeValue(buffer, value.encode());
    }    else if (value is LaunchTarget) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    }    else if (value is TelephonyEvent) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    }    else if (value is CallsStatus) {
      buffer.putUint8(139);
      writeValue(buffer, value.encode());
    }    else if (value is RecentCall) {
      buffer.putUint8(140);
      writeValue(buffer, value.encode());
    }    else if (value is PhoneContact) {
      buffer.putUint8(141);
      writeValue(buffer, value.encode());
    }    else if (value is CallbackTaskData) {
