      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 129:
        return PermissionState.decode(readValue(buffer)!);
      case 130:
        return SimInfo.decode(readValue(buffer)!);
      case 131:
        return DeviceFacts.decode(readValue(buffer)!);
      case 132:
        return KeyInfo.decode(readValue(buffer)!);
      case 133:
        return HttpRequestData.decode(readValue(buffer)!);
      case 134:
